def contact(lang):
 body=head(lang,'LET’S TALK',bi('从一次交流，<br>开始下一步。','A conversation.<br>A new possibility.')[lang],bi('无论是进入新市场、建立品牌，还是改善现有业务，都可以先和我们聊聊。','Whether you are entering a market, building a brand or improving an existing business, let’s start with a conversation.')[lang])
 body+='<section class="contact-layout wrap"><div><p class="eyebrow">GET IN TOUCH</p><a class="email-link" href="mailto:'+EMAIL+'">'+EMAIL+' ↗</a><p>'+bi('欢迎用中文或英文与我们联系。','We welcome enquiries in Chinese and English.')[lang]+'</p><div class="contact-note"><h3>'+bi('这些信息能帮助我们更快理解你。','A little context helps us understand.')[lang]+'</h3><p>'+bi('你的品牌或公司、目标市场、当前遇到的挑战，以及希望推进的时间。','Your brand or company, target markets, current challenges and your preferred timeline.')[lang]+'</p></div></div><form id="enquiry" data-email="'+EMAIL+'" data-lang="'+lang+'"><div class="form-row"><label>'+bi('你的称呼','Your name')[lang]+'<input name="name" autocomplete="name" required maxlength="100"></label><label>'+bi('公司 / 品牌','Company / brand')[lang]+'<input name="company" autocomplete="organization" maxlength="150"></label></div><label>'+bi('联系邮箱','Email address')[lang]+'<input name="email" type="email" autocomplete="email" required maxlength="200"></label><label>'+bi('想聊聊什么？','What would you like to discuss?')[lang]+'<textarea name="message" rows="5" required maxlength="3000" placeholder="'+bi('简单介绍项目、目标市场或你遇到的问题。','Tell us about your project, target market or challenge.')[lang]+'"></textarea></label><p class="form-note">'+bi('点击后会打开你的邮箱应用，内容由你确认后发送。此表单不会直接上传或保存信息。','This opens your email app. Review and send the message there. This form does not upload or store your details.')[lang]+'</p><button class="button" type="submit">'+bi('在邮箱中发送','Continue in email')[lang]+' ↗</button><p id="form-status" role="status"></p></form></section>'
 return body
descs=bi('威克斯结合消费者洞察、品牌创意与跨境电商经验，提供品牌策略、数字体验、渠道拓展与运营支持。','Wicks combines consumer insights, brand creativity and cross-border commerce to support brand strategy, digital experiences, channels and operations.')
for lang in ['zh','en']:
 for page,title,body in [('',bi('品牌建设与跨境经营','Brand building & cross-border commerce'),home(lang)),('services',bi('我们的服务','Our services'),services(lang)),('work',bi('项目案例','Our work'),work(lang)),('about',bi('关于我们','About us'),about(lang)),('contact',bi('联系我们','Contact us'),contact(lang))]+[('work/'+c['id'],bi(c['name'],c['name']),detail(lang,c)) for c in CASES]:
  d=OUT/lang/page;d.mkdir(parents=True,exist_ok=True);(d/'index.html').write_text(shell(lang,page,title[lang],body,descs[lang]))
(OUT/'index.html').write_text('<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta http-equiv="refresh" content="0;url=/zh/"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Wicks 威克斯</title><link rel="canonical" href="'+ORIGIN+'/zh/"></head><body><a href="/zh/">进入威克斯官网</a> · <a href="/en/">Visit Wicks in English</a></body></html>')
(OUT/'404.html').write_text('<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>页面未找到 | Wicks</title><link rel="stylesheet" href="/style.css"><main class="page-head wrap"><p class="eyebrow">404</p><h1>页面未找到。<br>Page not found.</h1><a class="button" href="/zh/">返回首页 / Home ↗</a></main></html>')
urls=[ORIGIN+'/'+str(p.parent.relative_to(OUT))+'/' for p in OUT.glob('*/**/index.html')]
(OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+u+'</loc></url>' for u in urls)+'</urlset>')
(OUT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+ORIGIN+'/sitemap.xml\n')
print('Generated',len(urls),'localized pages.')
